# Existing target/condition fixtures keep a complete two-branch configuration;
# each negative changes the named restriction instead of relying on incompleteness.
_gateway='<process id="p"><eventBasedGateway id="g"/><receiveTask id="a"/><receiveTask id="b"/><sequenceFlow id="f" sourceRef="g" targetRef="a"/><sequenceFlow id="h" sourceRef="g" targetRef="b"/></process>'
PAIRS['event-gateway-target']=(_gateway,_gateway.replace('<receiveTask id="a"/>','<task id="a"/>'))
PAIRS['event-gateway-conditions']=(_gateway,_gateway.replace('<eventBasedGateway id="g"/>','<eventBasedGateway id="g" default="f"/>'))
PAIRS['event-gateway-cardinality']=(_gateway,_gateway.replace('<sequenceFlow id="h" sourceRef="g" targetRef="b"/>',''))
PAIRS['event-gateway-configuration']=(_gateway,_gateway.replace('<receiveTask id="a"/>','<intermediateCatchEvent id="a"><messageEventDefinition/></intermediateCatchEvent>'))
PAIRS['event-gateway-instantiation']=(_gateway.replace('<eventBasedGateway id="g"/>','<eventBasedGateway id="g" instantiate="true" eventGatewayType="Parallel"/>'),_gateway.replace('<eventBasedGateway id="g"/>','<eventBasedGateway id="g" eventGatewayType="Parallel"/>'))
def document(body):
    return ('<definitions xmlns="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" targetNamespace="urn:independent-rules">'+body+'</definitions>').encode()
